mapper.update:
UPDATE oms_order_idempotency
SET order_id = #{orderId},
    status = 'SUCCESS',
    update_time = NOW()
WHERE member_id = #{memberId}
  AND idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = 'PROCESSING'

UPDATE pms_sku_stock
SET lock_stock = GREATEST(COALESCE(lock_stock, 0), 0) + #{quantity}
WHERE id = #{skuId}
  AND #{quantity} > 0
  AND COALESCE(stock, 0) >= 0
  AND COALESCE(stock, 0) - GREATEST(COALESCE(lock_stock, 0), 0) >= #{quantity}

UPDATE pms_sku_stock SET stock = CASE id
WHEN #{item.productSkuId} THEN stock - #{item.productQuantity}
END, lock_stock = CASE id
WHEN #{item.productSkuId} THEN lock_stock - #{item.productQuantity}
END WHERE id IN
#{item.productSkuId}

